UCoIChoice::UCoIChoice(){InitFont(FCoreStyle::GetDefaultFontStyle("Regular",12));InitForegroundColor(Paper);auto Style=GetWidgetStyle();Style.ComboButtonStyle.ButtonStyle.Normal.TintColor=FSlateColor(Ink);Style.ComboButtonStyle.ButtonStyle.Hovered.TintColor=FSlateColor(FLinearColor(.12f,.15f,.15f));Style.ComboButtonStyle.ButtonStyle.Pressed.TintColor=FSlateColor(Brass);SetWidgetStyle(Style);}
