UCoIActionButton::UCoIActionButton(){InitIsFocusable(false);OnClicked.AddDynamic(this,&UCoIActionButton::Dispatch);}
void UCoIActionButton::Dispatch(){if(OwnerHUD)OwnerHUD->Action(Action);}
UTextBlock* UCoIPlayerHUD::Text(UPanelWidget* Parent,const FString& Value,int32 Size,bool Gold){auto* T=WidgetTree->ConstructWidget<UTextBlock>();T->SetFont(FCoreStyle::GetDefaultFontStyle("Regular",Size));T->SetColorAndOpacity(Gold?Brass:Paper);T->SetText(FText::FromString(Value));T->SetAutoWrapText(true);if(Parent)Add(Parent,T);return T;}
UHorizontalBox* UCoIPlayerHUD::Row(UPanelWidget* Parent){auto* R=WidgetTree->ConstructWidget<UHorizontalBox>();if(Parent)Add(Parent,R);return R;}
