UComboBoxString* UCoIPlayerHUD::Choice(UPanelWidget* Parent,const FString& Key,const FString& Label,const TArray<TPair<FString,FString>>& Options,const FString& Default){auto* Box=WidgetTree->ConstructWidget<UVerticalBox>();Add(Parent,Box);if(auto* Cell=Cast<UHorizontalBoxSlot>(Box->Slot)){Cell->SetSize(FSlateChildSize(ESlateSizeRule::Fill));Cell->SetPadding(FMargin(0,0,12,0));}Text(Box,Label,11,true);auto* C=WidgetTree->ConstructWidget<UCoIChoice>();C->SetMaxListHeight(250);Add(Box,C);Choices.Add(Key,C);ChoiceValues.Add(Key,{});for(const auto& Pair:Options){FString Display=Pair.Value;while(ChoiceValues[Key].Contains(Display))Display+=TEXT(" ");C->AddOption(Display);ChoiceValues[Key].Add(Display,Pair.Key);if(Pair.Key==Default)C->SetSelectedOption(Display);}if(C->GetSelectedOption().IsEmpty()&&Options.Num())C->SetSelectedIndex(0);Selected.Add(Key,ChoiceValues[Key].FindRef(C->GetSelectedOption()));C->OnSelectionChanged.AddDynamic(this,&UCoIPlayerHUD::ChoiceChanged);C->SetToolTipText(FText::FromString(Label));return C;}
void UCoIPlayerHUD::Field(UPanelWidget* Parent,const FString& Key,const FString& Label,const FString& Value){auto* Box=WidgetTree->ConstructWidget<UVerticalBox>();Add(Parent,Box);if(auto* Cell=Cast<UHorizontalBoxSlot>(Box->Slot)){Cell->SetSize(FSlateChildSize(ESlateSizeRule::Fill));Cell->SetPadding(FMargin(0,0,12,0));}Text(Box,Label,11,true);auto* F=WidgetTree->ConstructWidget<UEditableTextBox>();auto Style=F->GetWidgetStyle();Style.SetFont(FCoreStyle::GetDefaultFontStyle("Regular",14));Style.TextStyle.SetColorAndOpacity(Ink);Style.SetForegroundColor(Ink).SetFocusedForegroundColor(Ink);F->SetWidgetStyle(Style);F->SetText(FText::FromString(Value));F->SetToolTipText(FText::FromString(Label+TEXT(" — nur ganze Zahlen")));Add(Box,F);Fields.Add(Key,F);F->OnTextChanged.AddDynamic(this,&UCoIPlayerHUD::InputChanged);}
