void UCoIPlayerHUD::NativeConstruct(){Super::NativeConstruct();SetIsFocusable(true);Sim=GetWorld()->GetSubsystem<UCoISimulationSubsystem>();if(Sim)Changed=Sim->OnChanged.AddUObject(this,&UCoIPlayerHUD::Refresh);Refresh();}
void UCoIPlayerHUD::NativeDestruct(){if(Sim)Sim->OnChanged.Remove(Changed);Sim=nullptr;Super::NativeDestruct();}
void UCoIPlayerHUD::NativeTick(const FGeometry& G,float Dt){Super::NativeTick(G,Dt);const auto Size=G.GetLocalSize();int32 Visible=Sim&&Sim->IsReady()?FMath::Clamp(Sim->GetSnapshot().Player.Events.Num(),1,(int32)Sim->GetSnapshot().Player.Rules.UiVisibleEvents):1;double Footer=36.+(Visible-1)*28.;auto Layout=[](UWidget* W,FVector2D P,FVector2D S){if(auto* C=Cast<UCanvasPanelSlot>(W->Slot)){C->SetPosition(P);C->SetSize(S);}};Layout(Top,{16,12},{Size.X-32,62});bool Economic=SelectionId.StartsWith(TEXT("route."))||Id(TEXT("map.layer"))==TEXT("supply")||Id(TEXT("map.layer"))==TEXT("price");Layout(SelectionPanel,{Size.X-322,82},{306,SelectionCollapsed?44.:Economic?FMath::Min(520.,Size.Y-112-Footer):264.});Layout(Work,{(Size.X-FMath::Min(1184.,Size.X-64))/2,140},{FMath::Min(1184.,Size.X-64),FMath::Min(650.,Size.Y-154-Footer)});Layout(Notices,{16,Size.Y-Footer-10},{Size.X-32,Footer});Layout(ModalShade,{0,76},{Size.X,Size.Y-76});FVector2D DS(FMath::Min(780.,Size.X-48),FMath::Min(530.,Size.Y-150));Layout(Dialog,{(Size.X-DS.X)/2,(Size.Y-DS.Y)/2+32},DS);}
bool UCoIPlayerHUD::OverlayCovered(FVector2D P,FVector2D Size) const {
 if(!DialogKind.IsEmpty())return true;
 // Map and HUD share the full-screen canvas. Compare local layout rectangles;
 // desktop window origins and cached child paint transforms are irrelevant here.
 for(const auto* W:{Top.Get(),Nav.Get(),Work.Get(),SelectionPanel.Get(),Notices.Get(),Debug.Get(),MapControls.Get(),MapLegend.Get()})if(W&&W->GetVisibility()!=ESlateVisibility::Collapsed)if(const auto* CanvasSlot=Cast<UCanvasPanelSlot>(W->Slot)){const auto A=CanvasSlot->GetPosition(),B=A+CanvasSlot->GetSize();if(P.X<=B.X&&P.X+Size.X>=A.X&&P.Y<=B.Y&&P.Y+Size.Y>=A.Y)return true;}
 return false;
}
bool UCoIPlayerHUD::PointerBlocked(FVector2D A) const {if(!DialogKind.IsEmpty())return true;for(const auto* W:{Top.Get(),Nav.Get(),Work.Get(),SelectionPanel.Get(),Notices.Get(),Debug.Get(),MapControls.Get(),MapLegend.Get()})if(W&&W->GetVisibility()!=ESlateVisibility::Collapsed&&W->GetCachedGeometry().IsUnderLocation(A))return true;return false;}
bool UCoIPlayerHUD::KeyboardBlocked() const{return !DialogKind.IsEmpty()||!View.IsEmpty();}
bool UCoIPlayerHUD::Escape(){if(!DialogKind.IsEmpty()){CloseDialog();return true;}if(!View.IsEmpty()){BuildView(TEXT(""));return true;}return false;}
FReply UCoIPlayerHUD::NativeOnPreviewKeyDown(const FGeometry& G,const FKeyEvent& E){if(E.GetKey()==EKeys::Escape&&Escape())return FReply::Handled();return Super::NativeOnPreviewKeyDown(G,E);}
FReply UCoIPlayerHUD::NativeOnMouseButtonDown(const FGeometry&,const FPointerEvent& E){return PointerBlocked(E.GetScreenSpacePosition())?FReply::Handled():FReply::Unhandled();}
FReply UCoIPlayerHUD::NativeOnMouseWheel(const FGeometry&,const FPointerEvent& E){return PointerBlocked(E.GetScreenSpacePosition())?FReply::Handled():FReply::Unhandled();}
FString UCoIPlayerHUD::Id(const FString& Key) const{return Selected.FindRef(Key);}
FString UCoIPlayerHUD::City(const FString& Key) const {if(Sim)if(const auto* P=Find(Sim->GetSnapshot().Player.Catalog.Places,Key))return P->Name;return Key.IsEmpty()?TEXT("Unterwegs"):TEXT("Ort nicht verfügbar");}
FString UCoIPlayerHUD::Good(const FString& Key) const {if(Sim)if(const auto* P=Find(Sim->GetSnapshot().Player.Catalog.Goods,Key))return P->Name;return TEXT("Leerfahrt");}
FString UCoIPlayerHUD::Store(const FString& Key) const {if(Sim)if(const auto* P=Find(Sim->GetSnapshot().Player.Stores,Key))return P->Name;return TEXT("Fracht unterwegs");}
FString UCoIPlayerHUD::Status(const FString& S) const {if(S==TEXT("open"))return TEXT("Offen");if(S==TEXT("filled"))return TEXT("Ausgeführt");if(S==TEXT("planned"))return TEXT("Geplant");if(S==TEXT("moving"))return TEXT("Unterwegs");if(S==TEXT("arrived"))return TEXT("Angekommen");if(S==TEXT("cancelled"))return TEXT("Storniert");if(S==TEXT("expired"))return TEXT("Abgelaufen");return TEXT("Beendet");}
FString UCoIPlayerHUD::Time(int64 Hour) const {FDateTime D;if(!Sim||!FDateTime::ParseIso8601(*(Sim->GetSnapshot().Player.StartDate+TEXT("T00:00:00Z")),D))return TEXT("Zeit nicht verfügbar");return (D+FTimespan::FromHours(Hour)).ToString(TEXT("%d.%m. %H:%M"));}

void UCoIPlayerHUD::MapSelection(const FString& IdValue,const FString& Summary){SelectionId=IdValue;SelectionSummary=Summary;RefreshSelection();RefreshMap();}
void UCoIPlayerHUD::RefreshSelection(){if(!Sim||!Sim->IsReady()||!SelectionText)return;const auto& S=Sim->GetSnapshot();FString T=SelectionSummary.IsEmpty()?TEXT("Ort auf der Karte auswählen"):SelectionSummary;if(const auto* C=Find(S.Player.Catalog.Places,SelectionId)){int64 Kg=0;for(const auto& I:S.Player.Stocks)if(const auto* W=Find(S.Player.Stores,I.StorageId);W&&W->CityId==C->Id)Kg+=I.QuantityKg;T=C->Name+TEXT(" · Stadt\nEigene Ware: ")+Quantity(Kg);}else for(const auto& R:S.Regions)if(R.Id==SelectionId){const auto* Place=S.Player.Catalog.Places.FindByPredicate([&](const FPlaceDef& P){return P.RegionId==R.Id;});T=(Place?Place->Name:TEXT("Region"))+TEXT(" · Wirtschaftsregion\nBevölkerung: ")+Number(R.Population);}if(const auto* R=Find(S.Player.Routes,SelectionId)){T=City(R->FromCityId)+TEXT(" → ")+City(R->ToCityId)+TEXT("\n")+(R->Own?TEXT("Eigene Route"):TEXT("Öffentliche Szenario-Aggregation"))+TEXT("\nAktive Lieferungen: ")+Number(R->Active)+TEXT(" · unterwegs: ")+Number(R->Moving);if(R->Own)T+=TEXT("\nEigene Fracht: ")+Quantity(R->OwnKg)+TEXT("\nNächste Ankunft: ")+Time(R->NextArrival);else T+=TEXT("\nKeine fremden Einzelaufträge oder Frachtmengen.");T+=TEXT("\nErneuter Klick wechselt nahe Routen.\nLkw-Symbole sind exemplarisch.");}else if(SelectionId.StartsWith(TEXT("route.")))T=TEXT("Diese Route ist nicht mehr aktiv oder nicht freigegeben.");
 if(RouteOpenButton)RouteOpenButton->SetIsEnabled(Find(S.Player.Routes,SelectionId)&&Find(S.Player.Routes,SelectionId)->Own);
 if(const auto* W=Find(S.Player.Stores,SelectionId))T=W->Name+TEXT("\n")+City(W->CityId)+TEXT(" · ")+(W->Own?TEXT("Eigenes Lager"):TEXT("Lagerstandort"));else if(const auto* J=Find(S.Player.Shipments,SelectionId))T=City(J->FromCityId)+TEXT(" → ")+City(J->ToCityId)+TEXT("\nEigener Auftrag · ")+Status(J->Status)+TEXT("\nAnkunft ")+Time(J->ArrivalStep);
 SelectionText->SetText(FText::FromString(T));SelectionText->SetVisibility(SelectionCollapsed?ESlateVisibility::Collapsed:ESlateVisibility::Visible);if(auto* B=Cast<UVerticalBox>(SelectionPanel->GetContent()))for(int32 I=1;I<B->GetChildrenCount();++I)B->GetChildAt(I)->SetVisibility(SelectionCollapsed?ESlateVisibility::Collapsed:ESlateVisibility::Visible);if(RouteOpenButton)RouteOpenButton->SetVisibility(!SelectionCollapsed&&SelectionId.StartsWith(TEXT("route."))?ESlateVisibility::Visible:ESlateVisibility::Collapsed);if(MetricDetails)MetricDetails->SetVisibility(!SelectionId.StartsWith(TEXT("route."))&&!SelectionCollapsed&&(Id(TEXT("map.layer"))==TEXT("supply")||Id(TEXT("map.layer"))==TEXT("price"))?ESlateVisibility::Visible:ESlateVisibility::Collapsed);}
void UCoIPlayerHUD::Refresh(){if(!Sim||!Sim->IsReady()){if(AccountText)AccountText->SetText(FText::FromString(TEXT("Simulation wird geladen")));return;}const auto& S=Sim->GetSnapshot();if(SeenGeneration!=S.Generation){SeenGeneration=S.Generation;SeenVersion=MAX_uint64;PendingTicket=0;Token=0;CloseDialog();}AccountText->SetText(FText::FromString(S.PlayerName+TEXT("\nFrei ")+Money(S.PlayerMoneyCents-S.PlayerReservedCents)+TEXT("  ·  Reserviert ")+Money(S.PlayerReservedCents)));AccountText->SetToolTipText(FText::FromString(TEXT("Gesamtkontostand: ")+Money(S.PlayerMoneyCents)+TEXT("\nVerfügbar = Kontostand minus Reservierungen. Reservierungen sind bereits im Kontostand enthalten.")));ClockText->SetText(FText::FromString(S.Date+TEXT("\n")+(Sim->IsPaused()?TEXT("Pausiert"):FString::Printf(TEXT("%dx · %.1f h/s"),Sim->GetSpeed(),Sim->GetDiagnostics().ActualHoursPerSecond))));RefreshMap();Caption(PauseButton,Sim->IsPaused()?TEXT("Start"):TEXT("Pause"));PauseButton->SetToolTipText(FText::FromString(Sim->IsPaused()?TEXT("Simulation fortsetzen; vorgemerkte Befehle werden im nächsten Schritt umgesetzt."):TEXT("Spielzeit pausieren.")));
 if(PendingTicket)for(const auto& R:Sim->GetCommandResults())if(R.Sequence==PendingTicket){PendingTicket=0;LastStatus.Empty();CloseDialog();break;}
 FString Notice=LastStatus;if(Notice.IsEmpty()&&S.Player.Events.Num()){int32 First=FMath::Max(0,S.Player.Events.Num()-(int32)S.Player.Rules.UiVisibleEvents);for(int32 I=First;I<S.Player.Events.Num();++I){const auto& E=S.Player.Events[I];if(!Notice.IsEmpty())Notice+=TEXT("\n");Notice+=Time(E.Hour)+TEXT(" · ")+E.Text;}}if(Notice.IsEmpty())Notice=TEXT("Fiktive Testdaten · Kauf und Transport sind getrennte Aufträge.");NoticeText->SetText(FText::FromString(Notice));NoticeText->SetToolTipText(FText::FromString(Notice));
 if(Debug->GetVisibility()!=ESlateVisibility::Collapsed){const auto& D=Sim->GetDiagnostics();DebugText->SetText(FText::FromString(FString::Printf(TEXT("TECHNISCHE DIAGNOSE\nSchritt %lld · Version %llu\nSchritt %.0f µs · Snapshot %.0f µs\nRückstau %lld · Warteschlange %lld\n\n%s"),S.Step,S.Version,D.StepMicros,D.SnapshotMicros,D.BacklogSteps,D.PendingCommands,*(S.EconomySummary+TEXT("\n")+(MapOwner?MapOwner->RouteDiagnostics():TEXT(""))))));}
 if(SeenVersion!=S.Version){RefreshSelection();if(!View.IsEmpty()&&FSlateApplication::Get().HasAnyMouseCaptor())return;SeenVersion=S.Version;if(!View.IsEmpty())RefreshTable();if(FormState&&!DialogKind.IsEmpty()){FormState->SetText(FText::FromString(PendingTicket?TEXT("Gesendet. Umsetzung beim nächsten Simulationsschritt; bei Pause bitte Start drücken."):QuoteVersion!=S.Version?TEXT("Vorschau ist älter als der aktuelle Zustand. Vor Bestätigung aktualisieren; die Ausführung prüft erneut."):TEXT("Unverbindliche Vorschau. Es ist noch nichts reserviert.")));}}
}
void UCoIPlayerHUD::Action(const FString& Key){FString Verb,Arg;if(!Key.Split(TEXT("|"),&Verb,&Arg))Verb=Key;
 if(Verb==TEXT("mode")){Selected.Add(TEXT("map.layer"),Arg);if(auto* C=Choices.FindRef(TEXT("map.layer")).Get()){Updating=true;for(const auto& V:ChoiceValues[TEXT("map.layer")])if(V.Value==Arg)C->SetSelectedOption(V.Key);Updating=false;}RefreshMap();RefreshSelection();return;}
 if(Verb==TEXT("mapPlan")){if(!Sim)return;const auto N=MapNavigation(Sim->GetSnapshot().Player,SelectionId,Id(TEXT("map.good")));BuildView(TEXT("Transporte"));OpenTransport(N.SourceInventoryId,false,N.TargetStorageId);return;}
 if(Verb==TEXT("centerStore")||Verb==TEXT("centerJob")){if(!Sim||!MapOwner)return;const FString CityId=MapObjectCity(Sim->GetSnapshot().Player,Arg);if(CityId.IsEmpty()){LastStatus=TEXT("Für dieses Objekt ist kein Kartenstandort verfügbar.");Refresh();return;}BuildView(TEXT(""));MapOwner->FocusObject(CityId,Arg);return;}
 if(Verb==TEXT("routeJobs")){if(Sim)if(const auto* R=Find(Sim->GetSnapshot().Player.Routes,SelectionId);R&&R->Own){FocusedObject=R->OwnJobs.Num()?R->OwnJobs[0]:TEXT("");BuildView(TEXT("Transporte"));}return;}
 if(Verb==TEXT("pause")){if(Sim)Sim->TogglePause();return;}if(Verb.StartsWith(TEXT("speed"))){if(Sim)Sim->SetSpeed(FCString::Atoi(*Verb.RightChop(5)));return;}if(Verb==TEXT("debug")){Debug->SetVisibility(Debug->GetVisibility()==ESlateVisibility::Collapsed?ESlateVisibility::Visible:ESlateVisibility::Collapsed);Refresh();return;}
 if(Verb==TEXT("view")){FocusedObject.Empty();BuildView(View==Arg?TEXT(""):Arg);return;}if(Verb==TEXT("allObjects")){FocusedObject.Empty();RefreshTable();return;}
 if(Verb==TEXT("closeWork")){BuildView(TEXT(""));return;}if(Verb==TEXT("closeDialog")){CloseDialog();return;}if(Verb==TEXT("collapse")){SelectionCollapsed=!SelectionCollapsed;RefreshSelection();return;}
 if(Verb==TEXT("selectedMarket")||Verb==TEXT("selectedStore")){FocusedObject.Empty();Selected.Add(TEXT("place"),TEXT(""));Selected.Add(TEXT("good"),Id(TEXT("map.good")));if(Sim){const auto& D=Sim->GetSnapshot().Player.Catalog;const FString CityId=MapObjectCity(Sim->GetSnapshot().Player,SelectionId);if(const auto* C=Find(D.Places,CityId))Selected.Add(TEXT("region"),C->RegionId);else if(Find(D.Regions,SelectionId))Selected.Add(TEXT("region"),SelectionId);}BuildView(Verb==TEXT("selectedMarket")?TEXT("Märkte"):TEXT("Lager"));return;}
 if(Verb==TEXT("buy")){OpenTrade(true,Arg);return;}if(Verb==TEXT("sell")){OpenTrade(false,Arg);return;}if(Verb==TEXT("haul")){OpenTransport(Arg);return;}if(Verb==TEXT("empty")){OpenTransport(Arg,true);return;}
 if(Verb==TEXT("cancelOrder")){OpenCancel(Arg,false);return;}if(Verb==TEXT("cancelHaul")){OpenCancel(Arg,true);return;}if(Verb==TEXT("preview")){Preview();return;}if(Verb==TEXT("confirm")){Confirm();return;}
 if(Verb==TEXT("event")&&Sim){if(const auto* E=Find(Sim->GetSnapshot().Player.Events,Arg)){FocusedObject=E->ObjectId;BuildView(E->Kind==TEXT("transport")?TEXT("Transporte"):E->Kind==TEXT("storage")?TEXT("Lager"):E->Kind==TEXT("company")?TEXT("Unternehmen"):TEXT("Märkte"));}return;}
 if(Verb==TEXT("notice")&&Sim&&Sim->GetSnapshot().Player.Events.Num()){const auto& E=Sim->GetSnapshot().Player.Events.Last();FocusedObject=E.ObjectId;BuildView(E.Kind==TEXT("transport")?TEXT("Transporte"):E.Kind==TEXT("storage")?TEXT("Lager"):E.Kind==TEXT("company")?TEXT("Unternehmen"):TEXT("Märkte"));return;}
}
void UCoIPlayerHUD::ChoiceChanged(FString,ESelectInfo::Type){if(Updating)return;const FString PreviousStock=Id(TEXT("form.stock"));for(const auto& Pair:Choices)Selected.Add(Pair.Key,ChoiceValues[Pair.Key].FindRef(Pair.Value->GetSelectedOption()));if(DialogKind==TEXT("haul")&&PreviousStock!=Id(TEXT("form.stock"))&&Sim){Updating=true;const auto& P=Sim->GetSnapshot().Player;const auto* Stock=Find(P.Stocks,Id(TEXT("form.stock")));if(auto* Combo=Choices.FindRef(TEXT("form.target")).Get()){const FString OldTarget=Id(TEXT("form.target"));Combo->ClearOptions();ChoiceValues[TEXT("form.target")].Reset();auto Option=[&](const FString& Key,const FString& Label){Combo->AddOption(Label);ChoiceValues[TEXT("form.target")].Add(Label,Key);if(Key==OldTarget)Combo->SetSelectedOption(Label);};Option(TEXT(""),TEXT("Ziel wählen"));for(const auto& W:P.Stores)if(W.Own||W.Public||(Stock&&W.AcceptedGoods.Contains(Stock->GoodId)))Option(W.Id,W.Name);if(Combo->GetSelectedOption().IsEmpty())Combo->SetSelectedIndex(0);Selected.Add(TEXT("form.target"),ChoiceValues[TEXT("form.target")].FindRef(Combo->GetSelectedOption()));}Updating=false;}
 RefreshMap();RefreshSelection();if(DialogKind.IsEmpty())RefreshTable();else {ValidDraft=false;if(ConfirmButton)ConfirmButton->SetIsEnabled(false);if(FormState)FormState->SetText(FText::FromString(TEXT("Auswahl geändert. Vorschau aktualisieren.")));}}
void UCoIPlayerHUD::InputChanged(const FText&){ValidDraft=false;if(ConfirmButton)ConfirmButton->SetIsEnabled(false);if(FormState)FormState->SetText(FText::FromString(TEXT("Eingabe geändert. Vorschau aktualisieren.")));}
bool UCoIPlayerHUD::ReadPositive(const FString& Key,int64& N,bool Zero) const {auto* F=Fields.FindRef(Key).Get();if(!F)return false;FString T=F->GetText().ToString();if(T.IsEmpty()||T.Len()>12)return false;for(TCHAR C:T)if(C<TEXT('0')||C>TEXT('9'))return false;return LexTryParseString(N,*T)&&(Zero?N>=0:N>0);}

