   FVehicleDef Type;Type.SpeedKmPerHour=V->Speed;Type.CostCentsPerKm=V->CostPerKm;FString Start=Empty?V->CityId:From->CityId,End=Empty?Id(TEXT("form.target")):To->CityId;const auto T=TransportTerms(P.Catalog,P.Rules,Start,End,Type,V->Own,P.Hour,P.Hour+Delay);
