void UCoIPlayerHUD::Confirm(){if(!ValidDraft||PendingTicket||!Sim)return;ValidDraft=false;ConfirmButton->SetIsEnabled(false);int64 Ticket=0;FString Error;if(!Sim->SubmitPlayer(Draft,Token,Ticket,Error)){FormState->SetText(FText::FromString(Error));return;}PendingTicket=Ticket;LastStatus=TEXT("Auftrag gesendet; Umsetzung beim nächsten Simulationsschritt. Bei Pause Start drücken.");FormState->SetText(FText::FromString(LastStatus));NoticeText->SetText(FText::FromString(LastStatus));}
